CREATE TABLE IF NOT EXISTS admins(id SERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS settings(id INT PRIMARY KEY DEFAULT 1, data JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sermons(id SERIAL PRIMARY KEY, title TEXT NOT NULL, category TEXT DEFAULT '', sermon_date DATE, length TEXT DEFAULT '', video_url TEXT DEFAULT '', audio_url TEXT DEFAULT '', pdf_url TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS events(id SERIAL PRIMARY KEY, title TEXT NOT NULL, when_text TEXT DEFAULT '', note TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS submissions(id SERIAL PRIMARY KEY, kind TEXT NOT NULL, name TEXT, email TEXT, phone TEXT, message TEXT, event_title TEXT, created_at TIMESTAMPTZ DEFAULT now());
